html:
{%- set fel = fel_print_context(doc) -%}
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set address = frappe.get_doc("Address", doc.company_address) if doc.company_address else None -%}
{%- set emitter_nit = company.nit_face_company or company.tax_id -%}
{%- if format_nit is defined and emitter_nit %}{% set emitter_nit = format_nit(emitter_nit) %}{% endif -%}
<style>
  .fel { font-size: 12px; color: #000; line-height: 1.4; overflow-wrap: anywhere; }
  .fel h2 { font-size: 15px; font-weight: 600; line-height: 1.25; margin: 0 0 4px; }
  .fel .doctitle { font-size: 19px; font-weight: 700; letter-spacing: .01em; line-height: 1.2; margin: 0; }
  .fel .dte { font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; color: #444; margin: 2px 0 6px; }
  .fel table { width: 100%; border-collapse: collapse; }
  .fel .hdr td { vertical-align: top; }
  .fel .lines th, .fel .lines td { border: 1px solid #999; padding: 5px 7px; }
  .fel .lines th { background: #f2f2f2; color: #000; font-weight: 600; text-align: left; }
  .fel .num { text-align: right; white-space: nowrap; }
  .fel .nw { white-space: nowrap; }
  .fel .box { border: 1px solid #999; padding: 8px 10px; margin-top: 10px; }
  .fel .warn { border: 2px solid #b00; color: #b00; padding: 8px 10px; margin: 10px 0; font-weight: bold; }
  .fel .void { border: 3px solid #b00; color: #b00; padding: 10px; margin: 10px 0; font-size: 16px; line-height: 1.3; font-weight: bold; text-align: center; }
  .fel .uuid { font-family: "Courier New", monospace; font-size: 11.5px; white-space: nowrap; }
  .fel .muted { color: #444; }
  .fel .totals { width: auto; min-width: 46%; margin-left: auto; }
  .fel .totals td { padding: 3px 0 3px 16px; }
  .fel .totals .grand td { border-top: 1.5px solid #000; padding-top: 6px; font-size: 17px; font-weight: 700; }
  .fel .qr img { width: 120px !important; height: 120px !important; }
  .fel .verify { font-size: 11px; word-break: break-all; }
  .fel .lines .desc { min-width: 40%; overflow-wrap: break-word; }
  @media screen and (max-width: 560px) {
    .fel .hdr > tbody > tr > td { display: block; width: 100% !important; text-align: left !important; }
    .fel .hdr > tbody > tr > td + td { margin-top: 10px; }
    .fel .uuid { white-space: normal; word-break: break-all; }
    .fel .lines th, .fel .lines td { padding: 4px; }
    .fel .lines .disc { display: none; }
    .fel .totals { width: 100%; }
  }
</style>
<div class="fel">
  <table class="hdr">
    <tr>
      <td style="width:56%">
        <h2>{{ company.facelec_trade_name or company.company_name }}</h2>
        <div>{% if company.facelec_trade_name and company.facelec_trade_name != company.company_name %}{{ company.company_name }} &middot; {% endif %}<span class="nw">NIT {{ emitter_nit }}</span></div>
        {%- if address %}
        <div>{{ address.address_line1 }}{% if address.address_line2 %}, {{ address.address_line2 }}{% endif %}</div>
        <div>{{ [address.city, address.state if address.state != address.city else None, address.country if address.country != "Guatemala" else None] | select | join(", ") }}</div>
        {%- endif %}
        {%- if fel.establecimiento %}<div>{{ _("Establecimiento") }} {{ fel.establecimiento.codigo }}{% if fel.establecimiento.nombre %}: {{ fel.establecimiento.nombre }}{% endif %}</div>{% endif %}
      </td>
      <td style="text-align:right">
        <div class="doctitle">{{ fel.title }}</div>
        <div class="dte">{{ _("Documento Tributario Electrónico") }}</div>
        {%- if fel.envio %}
        <div><span class="nw">{{ _("Serie") }} <b>{{ fel.envio.serie }}</b></span> <span class="nw">{{ _("Número") }} <b>{{ fel.envio.numero }}</b></span></div>
        <div>{{ _("Autorización") }}</div>
        <div class="uuid">{{ fel.envio.uuid }}</div>
        <div>{{ _("Certificación") }}: {{ fel.fecha_certificacion }}</div>
        {%- endif %}
        <div>{{ _("Emisión") }}: {{ frappe.utils.format_date(doc.posting_date) }}{% if doc.posting_time %} {{ (doc.posting_time | string)[:5] }}{% endif %}</div>
        {%- if fel.access_number %}<div>{{ _("Número de acceso") }}: {{ fel.access_number }}</div>{% endif %}
        {%- if fel.tipo_cambio %}<div>{{ _("Moneda") }} {{ doc.currency }} &middot; {{ _("Tipo de cambio") }} {{ fel.tipo_cambio }}</div>{% endif %}
      </td>
    </tr>
  </table>

  {%- if fel.anulado %}
  <div class="void">{{ _("DOCUMENTO ANULADO") }}{% if fel.anulado.fecha %} &middot; {{ fel.anulado.fecha }}{% endif %}
    {%- if fel.anulado.motivo %}<div style="font-size:12px; font-weight:normal">{{ _("Motivo") }}: {{ fel.anulado.motivo }}</div>{% endif %}
    {%- if fel.demo %}<div style="font-size:12px; font-weight:normal">{{ _("Documento de prueba (modo Demo): ni el documento ni su anulación se enviaron a SAT.") }}</div>{% endif %}
  </div>
  {%- elif fel.demo %}
  <div class="warn">{{ _("DOCUMENTO DE PRUEBA (modo Demo): no fue enviado a ningún certificador ni a SAT y no tiene validez fiscal.") }}</div>
  {%- elif fel.contingency and not fel.certified %}
  <div class="warn">{{ _("DOCUMENTO EMITIDO EN CONTINGENCIA: pendiente de certificación ante SAT.") }}</div>
  {%- elif not fel.certified %}
  <div class="warn">{{ _("DOCUMENTO NO CERTIFICADO: no tiene validez como DTE.") }}</div>
  {%- endif %}

  <div class="box">
    <div>{{ _("Cliente") }}: <b>{{ (doc.nombre_segun_sat or doc.customer_name) if not fel.consumidor_final or (doc.nombre_segun_sat or doc.customer_name) else _("CONSUMIDOR FINAL") }}</b></div>
    <div>{{ _("NIT / CUI") }}: {% if fel.consumidor_final %}CF &middot; {{ _("Consumidor final") }}{% else %}{{ fel.receptor_nit }}{% endif %}</div>
    {%- if doc.address_display %}<div>{{ _("Dirección") }}: {{ doc.address_display | striptags }}</div>{% endif %}
  </div>

  {%- set has_discount = doc.items | selectattr("discount_amount") | list | length > 0 -%}
  <table class="lines" style="margin-top:10px">
    <thead>
      <tr><th class="num">{{ _("Cant.") }}</th><th class="desc">{{ _("Descripción") }}</th><th class="num">{{ _("Precio unitario") }}</th>{% if has_discount %}<th class="num disc">{{ _("Descuento") }}</th>{% endif %}<th class="num">{{ _("Total") }}</th></tr>
    </thead>
    <tbody>
      {%- for item in doc.items %}
      <tr>
        <td class="num">{{ item.get_formatted("qty") }}</td>
        <td class="desc">{{ item.item_name }}</td>
        <td class="num">{{ item.get_formatted("rate") }}</td>
        {%- if has_discount %}<td class="num disc">{{ frappe.utils.fmt_money((item.discount_amount or 0) * item.qty, currency=doc.currency) }}</td>{% endif %}
        <td class="num">{{ item.get_formatted("amount") }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  {%- if fel.abonos %}
  <table class="lines" style="margin-top:10px; width:60%">
    <thead><tr><th>{{ _("Abono") }}</th><th>{{ _("Vencimiento") }}</th><th class="num">{{ _("Monto") }}</th></tr></thead>
    <tbody>
      {%- for abono in fel.abonos %}
      <tr><td>{{ abono.numero }}</td><td>{{ abono.vencimiento }}</td><td class="num">{{ frappe.utils.fmt_money(abono.monto, currency=doc.currency) }}</td></tr>
      {%- endfor %}
    </tbody>
  </table>
  {%- endif %}

  <table class="hdr" style="margin-top:10px">
    <tr>
      <td style="width:54%">
        <div><b>{{ currency_in_words(doc.grand_total, doc.currency) }}</b></div>
        {%- for frase in fel.frases %}<div><i>{{ frase }}</i></div>{% endfor %}
        {%- if fel.qr and not fel.demo and not fel.anulado %}
        <div class="qr" style="margin-top:8px">{{ fel.qr }}</div>
        <div class="muted">{{ _("Escanee para verificar el documento") }}</div>
        {%- if fel.verify_url %}<div class="muted verify">{{ _("o verifíquelo en") }} {{ fel.verify_url }}</div>{% endif %}
        {%- endif %}
      </td>
      <td>
        <table class="totals">
          <tr class="muted"><td>{{ _("Total sin impuestos") }}</td><td class="num">{{ doc.get_formatted("net_total") }}</td></tr>
          {%- for tax in doc.taxes %}{% if tax.tax_amount %}
          <tr><td>{{ tax.description or tax.account_head }}{% if tax.included_in_print_rate %} ({{ _("incluido en el precio") }}){% endif %}</td><td class="num">{{ tax.get_formatted("tax_amount") }}</td></tr>
          {%- endif %}{% endfor %}
          {%- if doc.discount_amount %}<tr><td>{{ _("Descuento") }}</td><td class="num">-{{ doc.get_formatted("discount_amount") }}</td></tr>{% endif %}
          <tr class="grand"><td>{{ _("TOTAL") }}</td><td class="num">{{ doc.get_formatted("grand_total") }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  {%- if fel.certifier and not fel.demo %}
  <div class="muted" style="margin-top:12px; text-align:center">{{ _("Certificador") }}: {{ fel.certifier.razon_social }} &middot; NIT {{ fel.certifier.nit }}</div>
  {%- endif %}
</div>
